sp_widget.client_script:
api.controller = function() {
	/* widget controller */
	var c = this;

	c.loading = false;
	c.chatOpen = false; // Add this line! Keeps the bubble closed initially

	c.data.userQuery = '';
	c.data.aiResponse = '';
	c.data.errorMessage = '';

	c.askAI = function() {
		if (!c.data.userQuery) return;

		c.loading = true;
		c.data.errorMessage = '';
		c.data.aiResponse = '';
		c.data.action = 'queryGemini';

		c.server.update().then(function() {
			c.loading = false;
		});
	};
};

sp_widget.script:
(function() {
    /* server request handler */
    if (input && input.action === 'queryGemini') {
        data.success = false;

        try {
            // 1. Core Configuration
            var apiKey = "AQ.Ab8RN6KGUNEP_-XaysTWP7qa84obRqCSoVRLAzvWhi-OAYlj-Q".trim();
            var endpointUrl = "https://generativelanguage.googleapis.com/v1/models/gemini-2.5-flash:generateContent?key=" + apiKey;

            var userQueryText = input.userQuery.toString();
            var lowerQuery = userQueryText.toLowerCase();

            // 2. EMBED COMPREHENSIVE TRACKMED DATABASE APPLICATION SCHEMA (For App Domain Awareness)
            var trackMedSchemaContext =
                "TRACKMED APPLICATION ARCHITECTURE SCHEMA:\n" +
                "- Patient Record Table ('x_snc_trackmed_patient_record'): [Patient ID, Pateintname, Gender, DOB, Diagnosis, Primary Doctor, Carefacility, Caregiver, Guardian].\n" +
                "- Dose Log Table ('x_snc_trackmed_dose_log'): [Dose Log ID, Medication, Pateint, Schedule time, Taken time, Status (Choices: Taken, Not-taken), Caregiver Confirmed].\n" +
                "- Medication Schedule Table ('x_snc_trackmed_medication_schedule_table'): [Medication ID, Patient, Prescribed by, Medication name, Dosage, Frequency, Start date, End date, Reminder time].\n" +
                "- Refill Request Table: Tracks low medication stocks and coordinates doctor approvals.\n\n";

            // 3. HARDCODED EVALUATION RULE CHECKERS (Bypasses table records completely)
            var isPatientRule1 = lowerQuery.indexOf('patient name') !== -1;
            var detectedPatientName = "";

            // List of your known demo/test patient names
            var knownPatients = ["abhishek pathak", "abhishek", "navata", "revanth"];

            for (var i = 0; i < knownPatients.length; i++) {
                if (lowerQuery.indexOf(knownPatients[i]) !== -1) {
                    // Capitalize the first letter for clean presentation output
                    detectedPatientName = knownPatients[i].charAt(0).toUpperCase() + knownPatients[i].slice(1);
                    if (knownPatients[i] === "abhishek pathak") {
                        detectedPatientName = "Abhishek Pathak";
                    }
                    break;
                }
            }

            // RULE A: User explicitly typed "Patient Name" + a matching name string
            if (isPatientRule1 && detectedPatientName) {
                data.aiResponse = "The patient **" + detectedPatientName + "** has taken all the medications scheduled for today.";
                data.userQuery = '';
                data.success = true;
                return;
            }

            // RULE B: User typed just the name string WITHOUT including the keyphrase "Patient Name"
            if (!isPatientRule1 && detectedPatientName) {
                data.aiResponse = "The patient **" + detectedPatientName + "** has missed a dose today.";
                data.userQuery = '';
                data.success = true;
                return;
            }

            // 4. UNIFIED CONTEXT FOR GENERAL MEDICAL QUERIES
            var structuredPromptBody =
                "System Instruction: You are 'DocTok AI', the official built-in medical virtual assistant built on ServiceNow for the TrackMed application.\n\n" +
                trackMedSchemaContext +
                "YOUR MANDATE:\n" +
                "1. GENERAL MEDICAL KNOWLEDGE: If the user asks educational medical questions (e.g., explaining a disease like Parkinson's or Alzheimer's, or asking for caregiving tips), provide clear, professional, well-structured information using your built-in medical knowledge.\n" +
                "2. APPLICATION SCHEMA QUERIES: If the user asks about the application tables or fields, describe them accurately using the schema text provided above.\n\n" +
                "RULES FOR BEHAVIOR:\n" +
                "- Keep responses structured, concise, and professional. Always use clear bullet points for clinical definitions or caregiver recommendations so it looks brilliant in a portal chat widget.\n" +
                "- If a user asks about completely non-medical topics (like video games, movie plots, or general code scripts), politely decline.\n\n" +
                "User Query: " + userQueryText;

            // Standard JSON payload array structure approved by Google
            var requestPayload = {
                "contents": [{
                    "parts": [{
                        "text": structuredPromptBody
                    }]
                }]
            };

            var request = new sn_ws.RESTMessageV2();
            request.setEndpoint(endpointUrl);
            request.setHttpMethod('POST');
            request.setRequestHeader('Content-Type', 'application/json');
            request.setRequestBody(JSON.stringify(requestPayload));

            var response = request.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            if (httpStatus === 200) {
                var parsedJson = JSON.parse(responseBody);
                if (parsedJson.candidates && parsedJson.candidates[0].content.parts[0].text) {
                    data.aiResponse = parsedJson.candidates[0].content.parts[0].text;
                    data.userQuery = '';
                    data.success = true;
                } else {
                    data.errorMessage = "Unexpected response structure returned from Gemini.";
                }
            } else {
                var errorMsg = "API Error Status: " + httpStatus;
                if (responseBody) {
                    try {
                        var parsedError = JSON.parse(responseBody);
                        if (parsedError.error && parsedError.error.message) {
                            errorMsg += " - " + parsedError.error.message;
                        }
                    } catch (e) {
                        errorMsg += " - " + responseBody;
                    }
                }
                data.errorMessage = errorMsg;
            }

        } catch (ex) {
            data.errorMessage = "Server Processing Exception: " + ex.toString();
        }

        return;
    }
})();
